<?php use VazinCMS\Security; ?><section class="title"><div><h1>وضعیت سامانه</h1><p>اطلاعات داخلی فقط برای مدیران</p></div></section><section class="grid stats"><?php foreach($details as $k=>$v): ?><article><b><?= Security::e((string)$v) ?></b><span><?= Security::e($k) ?></span></article><?php endforeach; ?></section><section class="panel"><h2>محصولات مستقل</h2><div class="table"><table><thead><tr><th>محصول</th><th>نوع</th><th>نسخه</th><th>وضعیت اتصال</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?= Security::e($p['name']) ?></td><td><?= Security::e($p['type']) ?></td><td><?= Security::e((string)$p['current_version']) ?></td><td><span class="badge muted"><?= Security::e($p['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section>
